 337: unpack_sample_table (
 338:     const struct _internal_exr_context* pctxt, exr_decode_pipeline_t* decode)
 339: {
 340:     exr_result_t rv           = EXR_ERR_SUCCESS;
 341:     int32_t      w            = decode->chunk.width;
 342:     int32_t      h            = decode->chunk.height;
 343:     int32_t      totsamp      = 0;
 344:     int32_t*     samptable    = decode->sample_count_table;
 345:     size_t       combSampSize = 0;
 346: 
 347:     for (int c = 0; c < decode->channel_count; ++c)
 348:         combSampSize += ((size_t) decode->channels[c].bytes_per_element);
 349: 
 350:     if ((decode->decode_flags & EXR_DECODE_SAMPLE_COUNTS_AS_INDIVIDUAL))
 351:     {
 352:         for (int32_t y = 0; y < h; ++y)
 353:         {
 354:             int32_t prevsamp = 0;
 355:             for (int32_t x = 0; x < w; ++x)
 356:             {
 357:                 int32_t nsamps =
 358:                     (int32_t) one_to_native32 ((uint32_t) samptable[y * w + x]);
 359:                 if (nsamps < 0) return EXR_ERR_INVALID_SAMPLE_DATA;
 360:                 samptable[y * w + x] = nsamps - prevsamp;
 361:                 prevsamp             = nsamps;
 362:             }
 363:             totsamp += prevsamp;
 364:         }
 365:         samptable[w * h] = totsamp;
 366:     }
 367:     else
 368:     {
 369:         for (int32_t y = 0; y < h; ++y)
 370:         {
 371:             int32_t prevsamp = 0;
 372:             for (int32_t x = 0; x < w; ++x)
 373:             {
