--- 178-340 ---
 178: LossyDctDecoder_base_construct (
 179:     LossyDctDecoder* d,
 180:     uint8_t*         packedAc,
 181:     uint8_t*         packedAcEnd,
 182:     uint8_t*         packedDc,
 183:     const uint16_t*  toLinear,
 184:     int              width,
 185:     int              height)
 186: {
 187:     d->_packedAcCount = 0;
 188:     d->_packedDcCount = 0;
 189:     d->_packedAc      = packedAc;
 190:     d->_packedAcEnd   = packedAcEnd;
 191:     d->_packedDc      = packedDc;
 192:     d->_toLinear      = toLinear;
 193:     d->_width         = width;
 194:     d->_height        = height;
 195:     if (d->_toLinear == NULL) d->_toLinear = dwaCompressorNoOp;
 196: 
 197:     //d->_isNativeXdr = GLOBAL_SYSTEM_LITTLE_ENDIAN;
 198: 
 199:     d->_channel_decode_data[0]    = NULL;
 200:     d->_channel_decode_data[1]    = NULL;
 201:     d->_channel_decode_data[2]    = NULL;
 202:     d->_channel_decode_data_count = 0;
 203: 
