 209: exr_result_t
 210: LossyDctDecoder_execute (
 211:     void* (*alloc_fn) (size_t), void (*free_fn) (void*), LossyDctDecoder* d)
 212: {
 213:     exr_result_t         rv;
 214:     int                  numComp = d->_channel_decode_data_count;
 215:     DctCoderChannelData* chanData[3];
 216:     int                  lastNonZero = 0;
 217:     int                  numBlocksX  = (int) (ceilf ((float) d->_width / 8.0f));
 218:     int                  numBlocksY = (int) (ceilf ((float) d->_height / 8.0f));
 219:     int                  leftoverX  = d->_width - (numBlocksX - 1) * 8;
 220:     int                  leftoverY  = d->_height - (numBlocksY - 1) * 8;
 221: 
 222:     int numFullBlocksX = (int) (floorf ((float) d->_width / 8.0f));
 223: 
 224:     uint16_t* currAcComp = (uint16_t*) (d->_packedAc);
 225:     uint16_t* acCompEnd  = (uint16_t*) (d->_packedAcEnd);
 226:     uint16_t* currDcComp[3];
 227:     uint8_t*  rowBlockHandle;
 228:     uint16_t* rowBlock[3];
 229: 
 230:     for (int chan = 0; chan < numComp; ++chan)
 231:     {
 232:         chanData[chan] = d->_channel_decode_data[chan];
 233:     }
 234: 
 235:     //
 236:     // Allocate a temp aligned buffer to hold a rows worth of full
 237:     // 8x8 half-float blocks
 238:     //
 239: 
 240:     rowBlockHandle = alloc_fn (
 241:         (size_t) numComp * (size_t) numBlocksX * 64 * sizeof (uint16_t) +
 242:         _SSE_ALIGNMENT);
 243:     if (!rowBlockHandle) return EXR_ERR_OUT_OF_MEMORY;
 244: 
 245:     rowBlock[0] = (uint16_t*) rowBlockHandle;
 246: 
 247:     for (int i = 0; i < _SSE_ALIGNMENT; ++i)
 248:     {
 249:         if (((uintptr_t) (rowBlockHandle + i) & _SSE_ALIGNMENT_MASK) == 0)
 250:             rowBlock[0] = (uint16_t*) (rowBlockHandle + i);
 251:     }
 252: 
 253:     for (int comp = 1; comp < numComp; ++comp)
 254:         rowBlock[comp] = rowBlock[comp - 1] + numBlocksX * 64;
 255: 
 256:     //
 257:     // Pack DC components together by common plane, so we can get
 258:     // a little more out of differencing them. We'll always have
 259:     // one component per block, so we can computed offsets.
 260:     //
 261: 
 262:     currDcComp[0] = (uint16_t*) d->_packedDc;
 263:     for (int comp = 1; comp < numComp; ++comp)
 264:         currDcComp[comp] = currDcComp[comp - 1] + numBlocksX * numBlocksY;
 265: 
 266:     for (int blocky = 0; blocky < numBlocksY; ++blocky)
 267:     {
 268:         int maxY = 8, maxX = 8;
 269:         if (blocky == numBlocksY - 1) maxY = leftoverY;
 270: 
 271:         for (int blockx = 0; blockx < numBlocksX; ++blockx)
 272:         {
 273:             uint8_t blockIsConstant = DWA_CLASSIFIER_TRUE;
 274: 
 275:             if (blockx == numBlocksX - 1) maxX = leftoverX;
 276: 
 277:             //
 278:             // If we can detect that the block is constant values
 279:             // (all components only have DC values, and all AC is 0),
 280:             // we can do everything only on 1 value, instead of all
 281:             // 64.
 282:             //
 283:             // This won't really help for regular images, but it is
 284:             // meant more for layers with large swaths of black
 285:             //
 286:             for (int comp = 0; comp < numComp; ++comp)
 287:             {
 288:                 uint16_t* halfZigData = chanData[comp]->_halfZigData;
 289:                 float*    dctData     = chanData[comp]->_dctData;
 290:                 //
 291:                 // DC component is stored separately
 292:                 //
 293: 
 294: #ifdef IMF_HAVE_SSE2
 295:                 {
 296:                     __m128i* dst = (__m128i*) halfZigData;
 297: 
 298:                     dst[7] = _mm_setzero_si128 ();
 299:                     dst[6] = _mm_setzero_si128 ();
 300:                     dst[5] = _mm_setzero_si128 ();
 301:                     dst[4] = _mm_setzero_si128 ();
 302:                     dst[3] = _mm_setzero_si128 ();
 303:                     dst[2] = _mm_setzero_si128 ();
 304:                     dst[1] = _mm_setzero_si128 ();
 305:                     dst[0] = _mm_insert_epi16 (
 306:                         _mm_setzero_si128 (), *currDcComp[comp]++, 0);
 307:                 }
 308: #else /* IMF_HAVE_SSE2 */
 309: 
 310:                 memset (halfZigData, 0, 64 * 2);
 311:                 halfZigData[0] = *currDcComp[comp]++;
 312: 
 313: #endif /* IMF_HAVE_SSE2 */
 314: 
 315:                 d->_packedDcCount++;
 316: 
 317:                 //
 318:                 // UnRLE the AC. This will modify currAcComp
 319:                 //
 320: 
 321:                 rv = LossyDctDecoder_unRleAc (
 322:                     d, &lastNonZero, &currAcComp, acCompEnd, halfZigData);
 323:                 if (rv != EXR_ERR_SUCCESS)
 324:                 {
 325:                     free_fn (rowBlockHandle);
 326:                     return rv;
 327:                 }
 328: 
 329:                 //
 330:                 // Convert from XDR to NATIVE
